import{St as e,at as t,it as n,st as r,t as i,vt as a}from"./chunks/framework.B8HA7oqK.js";var o=JSON.parse(`{"title":"Development Standards","description":"","frontmatter":{},"headers":[],"relativePath":"en/development/intro/guide.md","filePath":"en/development/intro/guide.md","lastUpdated":1780338995000}`),s={name:`en/development/intro/guide.md`};function c(i,o,s,c,l,u){let d=e(`Badge`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="development-standards" tabindex="-1">Development Standards <a class="header-anchor" href="#development-standards" aria-label="Permalink to “Development Standards”">​</a></h1><h2 id="basic" tabindex="-1">Basic <a class="header-anchor" href="#basic" aria-label="Permalink to “Basic”">​</a></h2><h3 id="version-control" tabindex="-1">Version Control <a class="header-anchor" href="#version-control" aria-label="Permalink to “Version Control”">​</a></h3><p>Project X code is hosted on GitHub:</p><ul><li>Xray Core: <a href="https://github.com/XTLS/Xray-core" target="_blank" rel="noreferrer">Xray-core</a></li><li>Install Script: <a href="https://github.com/XTLS/Xray-install" target="_blank" rel="noreferrer">Xray-install</a></li><li>Configuration Templates: <a href="https://github.com/XTLS/Xray-examples" target="_blank" rel="noreferrer">Xray-examples</a></li><li>Xray Documentation: <a href="https://github.com/XTLS/Xray-docs-next" target="_blank" rel="noreferrer">Xray-docs-next</a></li></ul><p>You can use <a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a> to fetch the code.</p><h3 id="branches" tabindex="-1">Branches <a class="header-anchor" href="#branches" aria-label="Permalink to “Branches”">​</a></h3><ul><li>The trunk branch of this project is <code>main</code>.</li><li>The release branch of this project is also <code>main</code>.</li><li>Ensure that <code>main</code> is compilable and usable at any given time.</li><li>If you need to develop new features, please create a new branch for development. After development is complete and fully tested, merge it back into the trunk branch.</li><li>Branches that have already been merged into the trunk and are no longer necessary should be deleted.</li></ul><h3 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to “Release”">​</a></h3>`,9),r(d,{text:`WIP`,type:`warning`}),o[1]||=t(`<ul><li>Establish two release channels: Bleeding Edge and Stable. <ul><li>Bleeding Edge: Can be daily builds, mainly used for specific testing scenarios, trying out new features, and obtaining immediate feedback for further improvement.</li><li>Stable: Scheduled updates (e.g., monthly), merging stable changes and releasing.</li></ul></li></ul><h3 id="referencing-other-projects" tabindex="-1">Referencing Other Projects <a class="header-anchor" href="#referencing-other-projects" aria-label="Permalink to “Referencing Other Projects”">​</a></h3><ul><li>Golang <ul><li>For product code, it is recommended to use the Golang standard library and libraries under <a href="https://pkg.go.dev/search?limit=25&amp;m=package&amp;q=golang.org%2Fx" target="_blank" rel="noreferrer">golang.org/x/</a>.</li><li>If you need to reference other projects, please create an issue for discussion beforehand.</li></ul></li><li>Others <ul><li>Tools that do not violate the agreements of either party and are helpful to the project can be used.</li></ul></li></ul><h2 id="development-process" tabindex="-1">Development Process <a class="header-anchor" href="#development-process" aria-label="Permalink to “Development Process”">​</a></h2><h3 id="before-writing-code" tabindex="-1">Before Writing Code <a class="header-anchor" href="#before-writing-code" aria-label="Permalink to “Before Writing Code”">​</a></h3><p>If you find any issues or have any ideas for the project, please create an <a href="https://github.com/XTLS/Xray-core/issues" target="_blank" rel="noreferrer">issue</a> for discussion to reduce repetitive work and time spent on code.</p><h3 id="modifying-code" tabindex="-1">Modifying Code <a class="header-anchor" href="#modifying-code" aria-label="Permalink to “Modifying Code”">​</a></h3><ul><li>Golang <ul><li>Please refer to <a href="https://golang.org/doc/effective_go.html" target="_blank" rel="noreferrer">Effective Go</a>.</li><li>Before every push, please run: <code>go generate core/format.go</code>.</li><li>If you need to modify protobuf, such as adding new configuration items, please run: <code>go generate core/proto.go</code>.</li><li>Before submitting a pull request, it is recommended to pass tests: <code>go test ./...</code>.</li><li>Before submitting a pull request, it is recommended that new code has over 70% code coverage.</li></ul></li><li>Others <ul><li>Please pay attention to code readability.</li></ul></li></ul><h3 id="pull-request" tabindex="-1">Pull Request <a class="header-anchor" href="#pull-request" aria-label="Permalink to “Pull Request”">​</a></h3><ul><li>Before submitting a PR, please run <code>git pull https://github.com/XTLS/Xray-core.git</code> to ensure the merge can proceed smoothly.</li><li>One PR should do one thing. If there are fixes for multiple bugs, please submit a separate PR for each bug.</li><li>Due to the special requirements of Golang (Package path), the PR process for Go projects differs from other projects. The recommended process is as follows: <ol><li>Fork this project first and create your own <code>github.com/&lt;your_name&gt;/Xray-core.git</code> repository.</li><li>Clone your own Xray repository locally: <code>git clone https://github.com/&lt;your_name&gt;/Xray-core.git</code>.</li><li>Create a new branch based on the <code>main</code> branch, e.g., <code>git branch issue24 main</code>.</li><li>Make changes and commit them on the newly created branch.</li><li>Before pushing the completed branch to your own repository, switch to the <code>main</code> branch and run <code>git pull https://github.com/XTLS/Xray-core.git</code> to pull the latest remote code.</li><li>If new remote code was pulled in the previous step, switch back to the branch you created and run <code>git rebase main</code> to perform the branch merge operation. If you encounter file conflicts, you need to resolve them.</li><li>After the previous step is completed, you can push your created branch to your own repository: <code>git push -u origin your-branch</code>.</li><li>Finally, send a PR from the newly pushed branch in your repository to the <code>main</code> branch of <code>XTLS/Xray-core</code>.</li><li>In the title and body of the PR, please fully describe the problem solved / new feature added / intention of the code changes, etc.</li><li>Wait patiently for the developers&#39; response.</li></ol></li></ul><h3 id="changes-to-code" tabindex="-1">Changes to Code <a class="header-anchor" href="#changes-to-code" aria-label="Permalink to “Changes to Code”">​</a></h3><h4 id="functional-issues" tabindex="-1">Functional Issues <a class="header-anchor" href="#functional-issues" aria-label="Permalink to “Functional Issues”">​</a></h4><p>Please submit at least one Test Case to verify changes to existing functions.</p><h4 id="performance-related" tabindex="-1">Performance Related <a class="header-anchor" href="#performance-related" aria-label="Permalink to “Performance Related”">​</a></h4><p>Please submit necessary test data to prove performance defects in existing code or performance improvements in new code.</p><h4 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to “New Features”">​</a></h4><ul><li>If the new feature does not affect existing features, please provide a switch (e.g., flag) that can turn it on/off, and keep the new feature off by default.</li><li>Before developing large new features (such as adding a new protocol), please submit an issue first and proceed with development after discussion.</li></ul><h4 id="others" tabindex="-1">Others <a class="header-anchor" href="#others" aria-label="Permalink to “Others”">​</a></h4><p>To be determined based on the specific situation.</p><h2 id="xray-coding-standards" tabindex="-1">Xray Coding Standards <a class="header-anchor" href="#xray-coding-standards" aria-label="Permalink to “Xray Coding Standards”">​</a></h2><p>The following applies to Golang code in Xray.</p><h3 id="code-structure" tabindex="-1">Code Structure <a class="header-anchor" href="#code-structure" aria-label="Permalink to “Code Structure”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span>Xray-core</span></span>
<span class="line"><span>├── app        // Application module</span></span>
<span class="line"><span>│   ├── router // Router</span></span>
<span class="line"><span>├── common     // Common code</span></span>
<span class="line"><span>├── proxy      // Communication protocols</span></span>
<span class="line"><span>│   ├── blackhole</span></span>
<span class="line"><span>│   ├── dokodemo-</span></span>
<span class="line"><span>│   ├── freedom</span></span>
<span class="line"><span>│   ├── socks</span></span>
<span class="line"><span>│   ├── vmess</span></span>
<span class="line"><span>├── transport  // Transport module</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="coding-standards" tabindex="-1">Coding Standards <a class="header-anchor" href="#coding-standards" aria-label="Permalink to “Coding Standards”">​</a></h3><p>Basically consistent with the practices recommended by official Golang documentation, with some exceptions. Written here to help everyone get familiar with Golang.</p><h4 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to “Naming”">​</a></h4><ul><li>Try to use single English words for file and directory names, such as <code>hello.go</code>. <ul><li>If unavoidable, use hyphens for directories / underscores for filenames to connect two (or more) words, e.g., <code>hello-world/hello_again.go</code>.</li><li>Test code should end with <code>_test.go</code>.</li></ul></li><li>Use PascalCase for types, such as <code>ConnectionHandler</code>. <ul><li>Abbreviations are not forced to be lowercase, i.e., <code>HTML</code> does not need to be written as <code>Html</code>.</li></ul></li><li>Public member variables also use PascalCase.</li><li>Private member variables use <a href="https://en.wikipedia.org/wiki/Camel_case" target="_blank" rel="noreferrer">lowerCamelCase</a>, such as <code>privateAttribute</code>.</li><li>To facilitate refactoring, it is recommended to use PascalCase for all methods. <ul><li>Put completely private types into <code>internal</code>.</li></ul></li></ul><h4 id="content-organization" tabindex="-1">Content Organization <a class="header-anchor" href="#content-organization" aria-label="Permalink to “Content Organization”">​</a></h4><ul><li>A file contains one main type and its related private functions, etc.</li><li>Test-related files, such as Mock utility classes, should be placed in the <code>testing</code> subdirectory.</li></ul><h4 id="int32range" tabindex="-1">Int32Range <a class="header-anchor" href="#int32range" aria-label="Permalink to “Int32Range”">​</a></h4><p><strong>For end user</strong></p><p>A value representing an optional range, which can be written in the following ways:</p><ul><li><p>A single number or range enclosed in quotes:</p><ul><li><code>&quot;&quot;</code> (Treated as 0. Note: Not setting a field at all and setting it to empty might be two different concepts for some fields.)</li><li><code>&quot;114&quot;</code></li><li><code>&quot;114-514&quot;</code></li></ul></li><li><p>An independent int (in this case, it can only be a single number):</p><ul><li><code>114</code></li></ul></li></ul><p><strong>For dev</strong></p><p>If you need to include a range in the configuration file, please use the <code>Int32Range</code> type.</p><p>Use <code>.From</code> and <code>.To</code> to get values. When From &gt; To (e.g., 1919-810), the values will be automatically swapped to ensure From is less than To. If you want to get the raw values, you can use <code>.Left</code> and <code>.Right</code>.</p>`,36)])}var l=i(s,[[`render`,c]]);export{o as __pageData,l as default};